 if actual is distinct from $spec$[{"name":"amount","type":"numeric(20,2)","notnull":false,"default":null,"generated":""},{"name":"amount_local","type":"numeric","notnull":false,"default":null,"generated":""},{"name":"applied_at","type":"timestamp without time zone","notnull":false,"default":null,"generated":""},{"name":"channel_type","type":"text","notnull":false,"default":null,"generated":""},{"name":"completed_at","type":"timestamp without time zone","notnull":false,"default":null,"generated":""},{"name":"country_code","type":"text","notnull":true,"default":null,"generated":""},{"name":"currency_local","type":"text","notnull":false,"default":null,"generated":""},{"name":"member_id","type":"text","notnull":false,"default":null,"generated":""},{"name":"member_level","type":"integer","notnull":false,"default":null,"generated":""},{"name":"money_format_version","type":"smallint","notnull":false,"default":null,"generated":""},{"name":"money_issue_code","type":"text","notnull":false,"default":null,"generated":""},{"name":"order_kind","type":"text","notnull":true,"default":null,"generated":""},{"name":"order_no","type":"text","notnull":true,"default":null,"generated":""},{"name":"platform","type":"text","notnull":true,"default":null,"generated":""},{"name":"raw_channel","type":"text","notnull":false,"default":null,"generated":""},{"name":"recharge_count","type":"integer","notnull":false,"default":null,"generated":""},{"name":"source_system","type":"text","notnull":true,"default":null,"generated":""},{"name":"status","type":"text","notnull":false,"default":null,"generated":""}]$spec$::jsonb then raise exception 'AR_SUB_FACT_SOURCE_COLUMNS_DRIFT';end if;
 if not exists(select 1 from pg_class c where c.oid='public.ar_collected_orders'::regclass and c.relowner='postgres'::regrole and c.relkind='r'and c.relpersistence='p'and c.relrowsecurity and not c.relforcerowsecurity and c.relacl::text='{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}')then raise exception 'AR_SUB_FACT_SOURCE_SECURITY_DRIFT';end if;
 if not exists(select 1 from pg_constraint c join pg_index i on i.indexrelid=c.conindid where c.conrelid='public.ar_collected_orders'::regclass and c.contype='p'and not c.condeferrable and not c.condeferred and c.convalidated and i.indimmediate and i.indisvalid and i.indisready and i.indislive and i.indisunique and i.indisprimary and i.indpred is null and i.indexprs is null and pg_get_constraintdef(c.oid)='PRIMARY KEY (source_system, country_code, platform, order_kind, order_no)')then raise exception 'AR_SUB_FACT_SOURCE_PK_DRIFT';end if;
 for spec in select * from(values('ar_collected_orders_order_no_check','lengthorder_no>=1andlengthorder_no<=160'),('ar_collected_orders_member_id_check','lengthmember_id>=1andlengthmember_id<=80'),('ar_collected_orders_status_check','lengthstatus<=160'),('ar_collected_orders_raw_channel_check','lengthraw_channel<=240'))v(name,expression)loop
