do $install$
declare f record;spec record;g text;
begin
 if to_regclass('private.ar_submission_typed_facts')is not null then
 for spec in select * from(values ('private.ar_submission_fact_scope(text,text)','61c447ed031f0d8c33b47ddf66051b0c',false,'i','s','sql','boolean','p_country text, p_platform text',0),
('private.guard_ar_submission_fact_write()','8a90ea2fb278583a37521fdc4de62765',false,'v','u','plpgsql','trigger','',0),
('private.guard_ar_submission_control_write()','b1a2d97a0272b6ba467db48cbaea005b',false,'v','u','plpgsql','trigger','',0),
('private.sync_ar_submission_typed_fact()','1f5f943b13f0cc4e843d0816baceefda',true,'v','u','plpgsql','trigger','',0),
('private.invalidate_ar_submission_fact_ready()','d3389ac2ed6bd9c6e357626c209b125c',true,'v','u','plpgsql','trigger','',0),
('private.ar_submission_fact_layout()','3e82491cdff83a6d98c9bf45abeb0ebd',false,'s','u','sql','jsonb','',0),
('private.ar_submission_fact_generation(text,text)','44e726b77cdbb15c8db7b0af81346a1b',false,'s','u','plpgsql','text','p_country text, p_platform text',0),
('private.ar_submission_fact_can_read(text,text,date,date)','59b1aaad5881647d9fb90dbb0074548d',false,'s','u','plpgsql','boolean','p_country text, p_platform text, p_from date, p_to date',0),
('private.backfill_ar_submission_fact(text,text,text,timestamp,timestamp,integer)','df7dd3ca8d84d01993d400359ed600e2',false,'v','u','plpgsql','bigint','p_country text, p_platform text, p_stream text, p_from timestamp without time zone, p_to timestamp without time zone, p_limit integer DEFAULT 1000',1))v(signature,hash,definer,volatility,parallel,language,result,arguments,defaults)loop
  select p.*,l.lanname into f from pg_proc p join pg_language l on l.oid=p.prolang where p.oid=to_regprocedure(spec.signature);
  if not found or md5(f.prosrc)<>spec.hash or f.proowner<>'postgres'::regrole or f.prosecdef<>spec.definer or f.provolatile<>spec.volatility::"char"or f.proparallel<>spec.parallel::"char"or f.lanname<>spec.language or f.prorettype<>spec.result::regtype or f.proretset or f.proisstrict or f.proleakproof or f.prokind<>'f'or f.pronargdefaults<>spec.defaults or f.provariadic<>0 or pg_get_function_arguments(f.oid)<>spec.arguments or f.proconfig is distinct from array['search_path=""']::text[]or f.proacl::text is distinct from '{postgres=X/postgres}'then raise exception 'AR_SUB_FACT_INSTALL_FUNCTION_DRIFT';end if;
 end loop;
 if private.ar_submission_fact_generation('IN','OKWIN')is null then raise exception 'AR_SUB_FACT_INSTALL_LAYOUT_DRIFT';end if;
  return;
 end if;
 if exists(select 1 from pg_proc p where p.pronamespace='private'::regnamespace and p.proname=any(array['ar_submission_fact_scope','guard_ar_submission_fact_write','guard_ar_submission_control_write','sync_ar_submission_typed_fact','invalidate_ar_submission_fact_ready','ar_submission_fact_layout','ar_submission_fact_generation','ar_submission_fact_can_read','backfill_ar_submission_fact']))or exists(select 1 from pg_class c where c.relnamespace='private'::regnamespace and c.relname=any(array['ar_submission_fact_epoch','ar_submission_day_ready','ar_submission_null_ready','ar_submission_future_ready']))or exists(select 1 from pg_trigger t where t.tgrelid='public.ar_collected_orders'::regclass and t.tgname like 'ar_sub_fact_source_%')then raise exception 'AR_SUB_FACT_INSTALL_NAME_COLLISION';end if;
 select p.*,l.lanname into f from pg_proc p join pg_language l on l.oid=p.prolang where p.oid=to_regprocedure('private.dashboard_admin_live_submission_analysis(jsonb)');
 if not found or md5(f.prosrc)<>'a8f8bb5de7d906675f5176c5eb4fcb70'or f.proowner<>'postgres'::regrole or not f.prosecdef or f.provolatile<>'s'or f.proparallel<>'u'or f.lanname<>'plpgsql'or f.prorettype<>'jsonb'::regtype or f.proretset or f.proisstrict or f.proleakproof or pg_get_function_arguments(f.oid)<>'p_request jsonb'or f.proconfig is distinct from array['search_path=""','jit=off','enable_nestloop=off']::text[]or f.proacl::text is distinct from '{postgres=X/postgres,authenticated=X/postgres}'then raise exception 'AR_SUB_FACT_INSTALL_READER_DRIFT';end if;
 select p.*,l.lanname into f from pg_proc p join pg_language l on l.oid=p.prolang where p.oid=to_regprocedure('private.dashboard_admin_ar_local_amount(text,text,text,smallint,numeric,text,text,numeric)');
 if not found or md5(f.prosrc)<>'dc8b95205e35b7366f4f9dbf052d307d'or f.proowner<>'postgres'::regrole or f.prosecdef or f.provolatile<>'i'or f.proparallel<>'s'or f.lanname<>'sql'or f.prorettype<>'numeric'::regtype or f.proretset or f.proisstrict or f.proleakproof or f.proconfig is distinct from array['search_path=""']::text[]or f.proacl::text is distinct from '{postgres=X/postgres}'then raise exception 'AR_SUB_FACT_INSTALL_AMOUNT_DRIFT';end if;
 execute $objects$create table private.ar_submission_typed_facts(
 source_system text not null,country_code text not null,platform text not null,order_kind text not null,order_no text not null,applied_at timestamp without time zone,completed_at timestamp without time zone,member_id text,status text,raw_channel text,member_level integer,recharge_count integer,channel_type text,money_format_version smallint,amount_local numeric,currency_local text,money_issue_code text,amount numeric(20,2),
 primary key(source_system,country_code,platform,order_kind,order_no),
 foreign key(source_system,country_code,platform,order_kind,order_no)references public.ar_collected_orders(source_system,country_code,platform,order_kind,order_no)on delete cascade deferrable initially deferred,
 constraint ar_sub_fact_population check(source_system='AR' and country_code='IN' and platform='OKWIN' and order_kind='recharge' and (applied_at>=timestamp '2026-10-10' or applied_at is null or(status='已支付' and completed_at>=timestamp '2026-10-10')) is true),
 check(length(order_no)between 1 and 160),check(length(member_id)between 1 and 80),check(length(status)<=160),check(length(raw_channel)<=240)
)with(fillfactor=90,autovacuum_vacuum_scale_factor=0.02,autovacuum_vacuum_threshold=1000,autovacuum_analyze_scale_factor=0.02,autovacuum_analyze_threshold=1000);
create index ar_submission_fact_applied_cover_idx on private.ar_submission_typed_facts(country_code,platform,applied_at)include(order_no,member_id,status,raw_channel,member_level,recharge_count);
create index ar_submission_fact_paid_cover_idx on private.ar_submission_typed_facts(country_code,platform,completed_at)include(member_id)where status='已支付';
create table private.ar_submission_fact_epoch(country_code text not null,platform text not null,epoch bigint not null check(epoch>=0),primary key(country_code,platform),check(country_code='IN'and platform='OKWIN'));
create table private.ar_submission_day_ready(country_code text not null,platform text not null,data_date date not null check(isfinite(data_date)and data_date>=date '2026-10-10'),generation text not null check(length(generation)=32),source_count bigint not null check(source_count>=0),validated_at timestamptz not null,primary key(country_code,platform,data_date),check(country_code='IN'and platform='OKWIN'));
create table private.ar_submission_null_ready(country_code text not null,platform text not null,generation text not null check(length(generation)=32),source_count bigint not null check(source_count>=0),validated_at timestamptz not null,primary key(country_code,platform),check(country_code='IN'and platform='OKWIN'));
create table private.ar_submission_future_ready(country_code text not null,platform text not null,future_from date not null check(isfinite(future_from)and future_from>=date '2026-10-10'),generation text not null check(length(generation)=32),validated_at timestamptz not null,primary key(country_code,platform),check(country_code='IN'and platform='OKWIN'));
insert into private.ar_submission_fact_epoch values('IN','OKWIN',0);
alter table private.ar_submission_typed_facts owner to postgres;alter table private.ar_submission_typed_facts enable row level security;revoke all on private.ar_submission_typed_facts from public,anon,authenticated,service_role;
alter table private.ar_submission_fact_epoch owner to postgres;alter table private.ar_submission_fact_epoch enable row level security;revoke all on private.ar_submission_fact_epoch from public,anon,authenticated,service_role;
alter table private.ar_submission_day_ready owner to postgres;alter table private.ar_submission_day_ready enable row level security;revoke all on private.ar_submission_day_ready from public,anon,authenticated,service_role;
alter table private.ar_submission_null_ready owner to postgres;alter table private.ar_submission_null_ready enable row level security;revoke all on private.ar_submission_null_ready from public,anon,authenticated,service_role;
alter table private.ar_submission_future_ready owner to postgres;alter table private.ar_submission_future_ready enable row level security;revoke all on private.ar_submission_future_ready from public,anon,authenticated,service_role;
create function private.ar_submission_fact_scope(p_country text,p_platform text)returns boolean language sql immutable parallel safe security invoker set search_path=''as $scope$select coalesce(p_country='IN'and p_platform='OKWIN',false);$scope$;
create function private.guard_ar_submission_fact_write()returns trigger language plpgsql volatile security invoker set search_path=''as $guard$
begin
 if current_user<>'postgres'or TG_RELID<>'private.ar_submission_typed_facts'::regclass or TG_WHEN<>'BEFORE'or TG_OP not in('INSERT','UPDATE','DELETE','TRUNCATE')then raise exception 'AR_SUB_FACT_WRITE_DENIED';end if;
 if TG_LEVEL='STATEMENT'and TG_OP='TRUNCATE'then return null;end if;
 if TG_LEVEL<>'ROW'then raise exception 'AR_SUB_FACT_WRITE_CONTEXT_INVALID';end if;
 if TG_OP='DELETE'then return old;end if;return new;
end;$guard$;
create function private.guard_ar_submission_control_write()returns trigger language plpgsql volatile security invoker set search_path=''as $guard_control$
begin
 if current_user<>'postgres'or TG_RELID<>all(array[to_regclass('private.ar_submission_fact_epoch'),to_regclass('private.ar_submission_day_ready'),to_regclass('private.ar_submission_null_ready'),to_regclass('private.ar_submission_future_ready')])or TG_WHEN<>'BEFORE'or TG_OP not in('INSERT','UPDATE','DELETE','TRUNCATE')then raise exception 'AR_SUB_FACT_CONTROL_WRITE_DENIED';end if;
 if TG_LEVEL='STATEMENT'and TG_OP='TRUNCATE'then return null;end if;
 if TG_LEVEL<>'ROW'then raise exception 'AR_SUB_FACT_CONTROL_WRITE_CONTEXT_INVALID';end if;
 if TG_OP='DELETE'then return old;end if;return new;
end;$guard_control$;
create function private.sync_ar_submission_typed_fact()returns trigger language plpgsql volatile security definer set search_path=''as $sync$
begin
 if TG_RELID<>'public.ar_collected_orders'::regclass or TG_WHEN<>'AFTER'or TG_OP not in('INSERT','UPDATE','DELETE','TRUNCATE')then raise exception 'AR_SUB_FACT_SYNC_CONTEXT_INVALID';end if;
 if TG_OP='TRUNCATE'and TG_LEVEL='STATEMENT'then
  -- The source FK forces facts into the same TRUNCATE/CASCADE operation.
  -- Do not recursively truncate a relation already active in that operation.
  update private.ar_submission_fact_epoch set epoch=epoch+1 where country_code='IN'and platform='OKWIN';
  delete from private.ar_submission_day_ready;delete from private.ar_submission_null_ready;delete from private.ar_submission_future_ready;return null;end if;
 if TG_LEVEL<>'ROW'then raise exception 'AR_SUB_FACT_SYNC_CONTEXT_INVALID';end if;
 if TG_OP='UPDATE'and (old.source_system,old.country_code,old.platform,old.order_kind,old.order_no,old.applied_at,old.completed_at,old.member_id,old.status,old.raw_channel,old.member_level,old.recharge_count,old.channel_type,old.money_format_version,old.amount_local::text,old.currency_local,old.money_issue_code,old.amount::text)is not distinct from (new.source_system,new.country_code,new.platform,new.order_kind,new.order_no,new.applied_at,new.completed_at,new.member_id,new.status,new.raw_channel,new.member_level,new.recharge_count,new.channel_type,new.money_format_version,new.amount_local::text,new.currency_local,new.money_issue_code,new.amount::text)then return new;end if;
 if TG_OP in('UPDATE','DELETE')and (old.source_system='AR' and old.country_code='IN' and old.platform='OKWIN' and old.order_kind='recharge' and (old.applied_at>=timestamp '2026-10-10' or old.applied_at is null or(old.status='已支付' and old.completed_at>=timestamp '2026-10-10')) is true)
  and (TG_OP='DELETE'or (old.source_system,old.country_code,old.platform,old.order_kind,old.order_no)is distinct from(new.source_system,new.country_code,new.platform,new.order_kind,new.order_no)or not coalesce((new.source_system='AR' and new.country_code='IN' and new.platform='OKWIN' and new.order_kind='recharge' and (new.applied_at>=timestamp '2026-10-10' or new.applied_at is null or(new.status='已支付' and new.completed_at>=timestamp '2026-10-10')) is true),false))then
  delete from private.ar_submission_typed_facts f where(f.source_system,f.country_code,f.platform,f.order_kind,f.order_no)=(old.source_system,old.country_code,old.platform,old.order_kind,old.order_no);
 end if;
 if TG_OP in('INSERT','UPDATE')and (new.source_system='AR' and new.country_code='IN' and new.platform='OKWIN' and new.order_kind='recharge' and (new.applied_at>=timestamp '2026-10-10' or new.applied_at is null or(new.status='已支付' and new.completed_at>=timestamp '2026-10-10')) is true)then
  insert into private.ar_submission_typed_facts(source_system,country_code,platform,order_kind,order_no,applied_at,completed_at,member_id,status,raw_channel,member_level,recharge_count,channel_type,money_format_version,amount_local,currency_local,money_issue_code,amount)values(new.source_system,new.country_code,new.platform,new.order_kind,new.order_no,new.applied_at,new.completed_at,new.member_id,new.status,new.raw_channel,new.member_level,new.recharge_count,new.channel_type,new.money_format_version,new.amount_local,new.currency_local,new.money_issue_code,new.amount)on conflict(source_system,country_code,platform,order_kind,order_no)do update set applied_at=excluded.applied_at,completed_at=excluded.completed_at,member_id=excluded.member_id,status=excluded.status,raw_channel=excluded.raw_channel,member_level=excluded.member_level,recharge_count=excluded.recharge_count,channel_type=excluded.channel_type,money_format_version=excluded.money_format_version,amount_local=excluded.amount_local,currency_local=excluded.currency_local,money_issue_code=excluded.money_issue_code,amount=excluded.amount;
 end if;
 if TG_OP='DELETE'then return old;end if;return new;
end;$sync$;
create function private.invalidate_ar_submission_fact_ready()returns trigger language plpgsql volatile security definer set search_path=''as $invalidate$
declare changed boolean:=true;
begin
 if TG_RELID<>'private.ar_submission_typed_facts'::regclass or TG_WHEN<>'AFTER'or TG_LEVEL<>'STATEMENT'or TG_OP not in('INSERT','UPDATE','DELETE','TRUNCATE')then raise exception 'AR_SUB_FACT_CONTROL_CONTEXT_INVALID';end if;
 if pg_trigger_depth()>1 then return null;end if;
 if TG_OP='INSERT'then select exists(select 1 from newfacts)into changed;
 elsif TG_OP='UPDATE'then select exists(select 1 from newfacts)into changed;
 elsif TG_OP='DELETE'then
  -- Native FK cascade deletes are source-atomic even if the outer trigger stack
  -- has unwound. Never treat owner maintenance with existing parents as sync.
  select exists(select 1 from oldfacts o where exists(select 1 from public.ar_collected_orders a where(a.source_system,a.country_code,a.platform,a.order_kind,a.order_no)=(o.source_system,o.country_code,o.platform,o.order_kind,o.order_no)))into changed;
 end if;
 if not changed then return null;end if;
 update private.ar_submission_fact_epoch set epoch=epoch+1 where country_code='IN'and platform='OKWIN';
 delete from private.ar_submission_day_ready;delete from private.ar_submission_null_ready;delete from private.ar_submission_future_ready;
 return null;
end;$invalidate$;
