create function private.ar_submission_fact_can_read(p_country text,p_platform text,p_from date,p_to date)returns boolean language plpgsql stable security invoker set search_path=''as $can_read$
declare g text;
begin
 if not coalesce(p_country='IN'and p_platform='OKWIN',false)or p_from is null or p_to is null or not isfinite(p_from)or not isfinite(p_to)or p_from<date '2026-10-10'or p_to<=p_from or p_to-p_from>62 then return false;end if;
 g:=private.ar_submission_fact_generation(p_country,p_platform);if g is null then return false;end if;
 if not exists(select 1 from private.ar_submission_null_ready where country_code=p_country and platform=p_platform and generation=g)then return false;end if;
 return not exists(select 1 from generate_series(p_from::timestamp,(p_to-1)::timestamp,interval '1 day')d where not exists(select 1 from private.ar_submission_day_ready r where r.country_code=p_country and r.platform=p_platform and r.data_date=d::date and r.generation=g)and not exists(select 1 from private.ar_submission_future_ready r where r.country_code=p_country and r.platform=p_platform and d::date>=r.future_from and r.generation=g));
end;$can_read$;
