create function private.backfill_ar_submission_fact(p_country text,p_platform text,p_stream text,p_from timestamp,p_to timestamp,p_limit integer default 1000)returns bigint language plpgsql volatile security invoker set search_path=''as $backfill$
declare v_filter text;v_written bigint;
begin
 if current_user<>'postgres'then raise exception 'AR_SUB_FACT_MAINTENANCE_OWNER_REQUIRED';end if;
 if not coalesce(p_country='IN'and p_platform='OKWIN',false)or p_stream is null or p_stream not in('cohort','success','null')or p_limit is null or p_limit<1 or p_limit>1000 then raise exception 'AR_SUB_FACT_BACKFILL_SCOPE_INVALID';end if;
 if p_stream='null'then
  if p_from is not null or p_to is not null then raise exception 'AR_SUB_FACT_BACKFILL_NULL_RANGE_INVALID';end if;
  v_filter:='a.applied_at is null';
 else
  if p_from is null or p_to is null or not isfinite(p_from)or not isfinite(p_to)or p_to<=p_from or p_to-p_from>interval '1 hour'or p_from<timestamp '2026-10-10'or p_to>timestamp '2026-10-12'then raise exception 'AR_SUB_FACT_BACKFILL_WINDOW_INVALID';end if;
  v_filter:=case when p_stream='cohort'then 'a.applied_at>=$3 and a.applied_at<$4'else 'a.status=''已支付''and a.completed_at>=$3 and a.completed_at<$4'end;
 end if;
 if private.ar_submission_fact_generation(p_country,p_platform)is null then raise exception 'AR_SUB_FACT_BACKFILL_GENERATION_INVALID';end if;
 execute 'with source as materialized(select a.source_system,a.country_code,a.platform,a.order_kind,a.order_no,a.applied_at,a.completed_at,a.member_id,a.status,a.raw_channel,a.member_level,a.recharge_count,a.channel_type,a.money_format_version,a.amount_local,a.currency_local,a.money_issue_code,a.amount from public.ar_collected_orders a where a.source_system=''AR''and a.country_code=$1 and a.platform=$2 and a.order_kind=''recharge''and('||v_filter||')and not exists(select 1 from private.ar_submission_typed_facts f where(f.source_system,f.country_code,f.platform,f.order_kind,f.order_no)=(a.source_system,a.country_code,a.platform,a.order_kind,a.order_no))limit $5 for share of a skip locked),written as(insert into private.ar_submission_typed_facts(source_system,country_code,platform,order_kind,order_no,applied_at,completed_at,member_id,status,raw_channel,member_level,recharge_count,channel_type,money_format_version,amount_local,currency_local,money_issue_code,amount)select * from source on conflict(source_system,country_code,platform,order_kind,order_no)do nothing returning 1)select count(*)from written'
 into v_written using p_country,p_platform,p_from,p_to,p_limit;
 return v_written;
end;$backfill$;
